(() => {
  const lists = [...document.querySelectorAll('*')].filter(e => ['To Do','In Progress','Done'].includes(e.textContent.trim()) && e.children.length===0);
  const cardEls = [...document.querySelectorAll('[class*="card"]')].map(e=>e.className);
  const seed = [...document.querySelectorAll('*')].filter(e => e.children.length===0 && e.textContent.trim().startsWith('Seed:')).map(e=>e.textContent.trim());
  const scrollable = [...document.querySelectorAll('*')].filter(e=> e.scrollHeight > e.clientHeight+5).map(e=>({cls:e.className, sh:e.scrollHeight, ch:e.clientHeight}));
  return {seed:[...new Set(seed)], scrollable};
})()
